// Package timeutil owns time-boundary rules shared by security and models.
// It does not replace the time.Time representation generated by SQLC.
package timeutil

import "time"

// SecondsCeil converts positive durations to whole Redis TTL seconds.
// Truncation turns positive sub-second limits into EXPIRE 0 (no protection).
// Nonpositive durations return zero so callers can reject invalid policies.
func SecondsCeil(duration time.Duration) int64 {
	if duration <= 0 {
		return 0
	}
	seconds := int64(duration / time.Second)
	if duration%time.Second != 0 {
		seconds++
	}
	return seconds
}
